import React from 'react';
import { Paper, Typography, List, ListItem, ListItemIcon, ListItemText, Divider, Box } from '@mui/material';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import CategoryIcon from '@mui/icons-material/Category';
import ContentCutIcon from '@mui/icons-material/ContentCut';
import EnhancedEncryptionIcon from '@mui/icons-material/EnhancedEncryption';
import TableChartIcon from '@mui/icons-material/TableChart';
import SearchIcon from '@mui/icons-material/Search';
import UploadFileIcon from '@mui/icons-material/UploadFile';

const SystemFeatures = () => {
  const features = [
    {
      icon: <AccountTreeIcon color="primary" />,
      name: "Document Structure Awareness",
      description: "Understanding document hierarchy and sections"
    },
    {
      icon: <CategoryIcon color="primary" />,
      name: "Question Classification",
      description: "Targeting relevant sections based on question type"
    },
    {
      icon: <ContentCutIcon color="primary" />,
      name: "Smart Chunking",
      description: "Preserving section context and boundaries"
    },
    {
      icon: <EnhancedEncryptionIcon color="primary" />,
      name: "Enhanced Embeddings",
      description: "Including section metadata in vector representations"
    },
    {
      icon: <TableChartIcon color="primary" />,
      name: "Table Handling",
      description: "Special processing for tables and schedules"
    },
    {
      icon: <SearchIcon color="primary" />,
      name: "Specialized Retrieval",
      description: "Different strategies for different question types"
    }
  ];

  return (
    <Paper sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">System Features</Typography>
      </Box>
      <Divider sx={{ mb: 2 }} />
      <List dense>
        {features.map((feature, index) => (
          <ListItem key={index}>
            <ListItemIcon>
              {feature.icon}
            </ListItemIcon>
            <ListItemText 
              primary={feature.name}
              secondary={feature.description}
            />
          </ListItem>
        ))}
      </List>

      <Box sx={{ mt: 4, p: 2, bgcolor: '#f5f7ff', borderRadius: 2 }}>
        <Typography variant="subtitle2" sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
          <UploadFileIcon fontSize="small" sx={{ mr: 1 }} /> 
          Upload a Document
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Upload your own protocol document to analyze it with our enhanced RAG system.
        </Typography>
      </Box>
    </Paper>
  );
};

export default SystemFeatures;
